import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.RequestPermissions{EntityUniqueID: 7, PermissionLevel: 2, RequestedPermissions: 192}
OPERATOR = bytes.fromhex("070000000000000004c000")

# generated by gophertunnel b8bd735:
# &packet.RequestPermissions{EntityUniqueID: -1, PermissionLevel: 3, RequestedPermissions: 255}
NEGATIVE_TARGET = bytes.fromhex("ffffffffffffffff06ff00")

# generated by gophertunnel b8bd735:
# &packet.RequestPermissions{EntityUniqueID: 0, PermissionLevel: 0, RequestedPermissions: 256}
HIGH_FLAG = bytes.fromhex("0000000000000000000001")

GOLDENS = [
    pytest.param(
        v2168.RequestPermissionsPacket(
            target_player_id=7,
            player_permissions=v2168.PlayerPermissionLevel.OPERATOR,
            custom_permission_flags=192,
        ),
        OPERATOR,
        id="operator",
    ),
    pytest.param(
        v2168.RequestPermissionsPacket(
            target_player_id=-1,
            player_permissions=v2168.PlayerPermissionLevel.CUSTOM,
            custom_permission_flags=255,
        ),
        NEGATIVE_TARGET,
        id="negative-target-as-a-fixed-int64",
    ),
    pytest.param(
        v2168.RequestPermissionsPacket(
            target_player_id=0,
            player_permissions=v2168.PlayerPermissionLevel.VISITOR,
            custom_permission_flags=0x0100,
        ),
        HIGH_FLAG,
        id="flags-as-a-fixed-little-endian-uint16",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_request_permissions_is_packet_185(version):
    assert version.PACKETS[185] is version.RequestPermissionsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_permissions_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_permissions_decodes_from_its_golden(packet, golden):
    assert v2168.RequestPermissionsPacket.from_bytes(golden) == packet


def test_the_custom_permission_flags_or_together_into_the_operator_golden():
    custom = v2168.RequestPermissionsPacket.CustomPermissions
    assert custom.OPERATOR_COMMANDS | custom.TELEPORT == 192
